import json
import gurobipy as gp
from gurobipy import GRB

# Data
periods = list(range(1, 21))

demand = {
    1: 10, 2: 37, 3: 34, 4: 10, 5: 36, 6: 42, 7: 11, 8: 14, 9: 33, 10: 50,
    11: 29, 12: 42, 13: 20, 14: 37, 15: 16, 16: 28, 17: 45, 18: 44, 19: 32, 20: 22
}
setup_cost = {
    1: 482, 2: 176, 3: 257, 4: 105, 5: 211, 6: 218, 7: 393, 8: 469, 9: 346, 10: 123,
    11: 244, 12: 228, 13: 213, 14: 298, 15: 322, 16: 269, 17: 494, 18: 362, 19: 223, 20: 428
}
prod_cost = {t: 0 for t in periods}
holding_cost = {
    1: 1, 2: 1, 3: 4, 4: 4, 5: 3, 6: 2, 7: 4, 8: 2, 9: 1, 10: 2,
    11: 3, 12: 5, 13: 3, 14: 4, 15: 2, 16: 5, 17: 4, 18: 1, 19: 4, 20: 2
}
capacity = {
    1: 10, 2: 37, 3: 34, 4: 11, 5: 41, 6: 52, 7: 13, 8: 13, 9: 34, 10: 75,
    11: 37, 12: 38, 13: 28, 14: 45, 15: 18, 16: 21, 17: 63, 18: 58, 19: 42, 20: 18
}

# Model
m = gp.Model("single_item_lot_sizing")
m.Params.OutputFlag = 0

x = m.addVars(periods, lb=0.0, vtype=GRB.CONTINUOUS, name="production")
I = m.addVars(periods, lb=0.0, vtype=GRB.CONTINUOUS, name="inventory")
y = m.addVars(periods, vtype=GRB.BINARY, name="setup")

# Capacity with setup
for t in periods:
    m.addConstr(x[t] <= capacity[t] * y[t], name=f"cap_{t}")

# Inventory balance
for t in periods:
    if t == 1:
        m.addConstr(x[t] == demand[t] + I[t], name=f"balance_{t}")
    else:
        m.addConstr(I[t - 1] + x[t] == demand[t] + I[t], name=f"balance_{t}")

# No ending inventory after horizon
m.addConstr(I[20] == 0, name="terminal_inventory")

# Objective
m.setObjective(
    gp.quicksum(setup_cost[t] * y[t] + prod_cost[t] * x[t] + holding_cost[t] * I[t] for t in periods),
    GRB.MINIMIZE
)

m.optimize()

production = {str(t): int(round(x[t].X)) for t in periods}
result = {
    "production": production,
    "objective_value": float(m.ObjVal)
}

print(json.dumps(result))
